describe('OverridesNavigatorView', () => {
  setupRuntimeHooks();
  setupLocaleHooks();

  let workspace: Workspace.Workspace.WorkspaceImpl;
  let backend: MockDebuggerBackend;

  beforeEach(() => {
    backend = new MockDebuggerBackend();
    workspace = backend.universe.workspace;
    const targetManager = backend.universe.targetManager;

    const actionRegistryInstance = UI.ActionRegistry.ActionRegistry.instance({forceNew: true});

    sinon.stub(Workspace.Workspace.WorkspaceImpl, 'instance').returns(workspace);
    sinon.stub(SDK.TargetManager.TargetManager, 'instance').returns(targetManager);
    sinon.stub(Workspace.IgnoreListManager.IgnoreListManager, 'instance').returns(backend.universe.ignoreListManager);
    sinon.stub(Common.Settings.Settings, 'instance').returns(backend.universe.settings);

    UI.ShortcutRegistry.ShortcutRegistry.instance({forceNew: true, actionRegistry: actionRegistryInstance});

    const debuggerWorkspaceBinding = backend.universe.debuggerWorkspaceBinding;
    const breakpointManager = Breakpoints.BreakpointManager.BreakpointManager.instance({
      forceNew: true,
      targetManager,
      workspace,
      debuggerWorkspaceBinding,
      settings: backend.universe.settings,
    });
    Persistence.Persistence.PersistenceImpl.instance({forceNew: true, workspace, breakpointManager});
    sinon.stub(Persistence.NetworkPersistenceManager.NetworkPersistenceManager, 'instance')
        .returns(backend.universe.networkPersistenceManager);

    setTestUniverseForWidgets(backend.universe);
  });

  async function createOverridesNavigatorView(): Promise<Sources.NavigatorView.NavigatorView> {
    const overridesNavigatorView = Sources.SourcesNavigator.OverridesNavigatorView.instance({forceNew: true});
    renderElementIntoDOM(overridesNavigatorView, {includeCommonStyles: true});
    await overridesNavigatorView.updateComplete;
    const navigatorView =
        overridesNavigatorView.children().find(child => child instanceof Sources.NavigatorView.NavigatorView);
    assert.exists(navigatorView);
    await navigatorView.updateComplete;
    navigatorView.contentElement.querySelector<UI.TreeOutline.TreeViewElement>('devtools-tree')
        ?.flushPendingUpdatesForTesting();
    await raf();
    return navigatorView;
  }

  it('renders the empty state with placeholder', async () => {
    await createOverridesNavigatorView();

    await assertScreenshot('sources/overrides-navigator-empty.png');
  });

  it('marks override items as active (has-mapped-files) when overrides are enabled', async () => {
    const {project} = createFileSystemUISourceCode({
      url: urlString`file:///home/workspace/overrides/.headers`,
      mimeType: 'text/plain',
      fileSystemPath: 'file:///home/workspace/overrides',
      type: Persistence.PlatformFileSystem.PlatformFileSystemType.OVERRIDES,
      universe: backend.universe,
    });

    Common.Settings.Settings.instance()
        .resolve(Persistence.NetworkPersistenceManager.persistenceNetworkOverridesEnabledSettingDescriptor)
        .set(true);

    const navigatorView = await createOverridesNavigatorView();

    await assertScreenshot('sources/overrides-navigator-populated.png');

    const rootElement = getTreeOutline(navigatorView).rootElement();
    const children = rootElement.children();
    assert.lengthOf(children, 1);
    const overridesNode = children[0];
    assert.isTrue(overridesNode.listItemElement.classList.contains('has-mapped-files'));

    // Setup a listener promise since toggling the 'persistence-network-overrides-enabled' will fire an event
    const updatePromise = Persistence.NetworkPersistenceManager.NetworkPersistenceManager.instance().once(
        Persistence.NetworkPersistenceManager.Events.LOCAL_OVERRIDES_PROJECT_UPDATED);

    Common.Settings.Settings.instance()
        .resolve(Persistence.NetworkPersistenceManager.persistenceNetworkOverridesEnabledSettingDescriptor)
        .set(false);
    // Waiting for the event to be fired
    await updatePromise;
    await navigatorView.updateComplete;

    const disabledOverridesNode = getTreeOutline(navigatorView).rootElement().children()[0];
    assert.isFalse(disabledOverridesNode.listItemElement.classList.contains('has-mapped-files'));

    project.removeProject();
  });

  it('creates the checkbox for enabling local overrides only once', async () => {
    const networkPersistenceManager = Persistence.NetworkPersistenceManager.NetworkPersistenceManager.instance();
    const enabledSetting = Common.Settings.Settings.instance().resolve(
        Persistence.NetworkPersistenceManager.persistenceNetworkOverridesEnabledSettingDescriptor);
    enabledSetting.set(true);
    const projectChanged = networkPersistenceManager.once(Persistence.NetworkPersistenceManager.Events.PROJECT_CHANGED);
    const {project} = createFileSystemUISourceCode({
      url: urlString`file:///home/workspace/overrides/.headers`,
      mimeType: 'text/plain',
      fileSystemPath: 'file:///home/workspace/overrides',
      type: Persistence.PlatformFileSystem.PlatformFileSystemType.OVERRIDES,
      universe: backend.universe,
    });
    await projectChanged;

    const countSettingListeners = (): number =>
        Common.Settings.Settings.instance().eventTargetForTest.listeners?.get(enabledSetting.name)?.size ?? 0;
    const navigatorView = Sources.SourcesNavigator.OverridesNavigatorView.instance({forceNew: true});
    renderElementIntoDOM(navigatorView);
    await navigatorView.updateComplete;
    const toolbar = navigatorView.contentElement.querySelector('.navigator-toolbar');
    assert.exists(toolbar);
    const checkbox = toolbar.querySelector('devtools-checkbox');
    assert.exists(checkbox);
    assert.isTrue(checkbox.checked);
    const listenerCount = countSettingListeners();

    // Adding or removing any project other than a file system updates the toolbar.
    const {project: networkProject} = createContentProviderUISourceCodes({
      items: [],
      projectType: Workspace.Workspace.projectTypes.Network,
      universe: backend.universe,
    });
    networkProject.removeProject();
    // So does disabling local overrides.
    const overridesUpdated =
        networkPersistenceManager.once(Persistence.NetworkPersistenceManager.Events.LOCAL_OVERRIDES_PROJECT_UPDATED);
    enabledSetting.set(false);
    await overridesUpdated;
    await navigatorView.updateComplete;

    assert.strictEqual(countSettingListeners(), listenerCount);
    const checkboxes = toolbar.querySelectorAll('devtools-checkbox');
    assert.lengthOf(checkboxes, 1);
    assert.strictEqual(checkboxes[0], checkbox);
    assert.isFalse(checkbox.checked);

    navigatorView.detach();
    project.removeProject();
    await navigatorView.updateComplete;
  });
});
